import { 
  PlaneGeometry, 
  Group, 
  Mesh, 
  Vector2 
} from 'three/webgpu';
import { MeshBasicNodeMaterial } from 'three/webgpu';

export default function createNode(config, ctx) {
  const group = new Group();
  const { imageUrl, scenePosition, sceneRotation, sceneScale, textContent, atlasRegion } = config;

  // Atlas region: source rect x, y, width, height (default from config or spec)
  const region = atlasRegion || { x: 0, y: 0, width: 512, height: 320 };

  // Create a plane with aspect ratio matching the atlas region
  const aspect = region.width / region.height;
  const geometry = new PlaneGeometry(aspect, 1);

  // Material: basic with placeholder color (will be replaced by texture)
  const material = new MeshBasicNodeMaterial({
    color: config.colors?.surface || '#0b0b10' // fallback
  });

  const mesh = new Mesh(geometry, material);
  group.add(mesh);

  // Load texture
  if (imageUrl) {
    ctx.textureLoader.loadTexture(imageUrl).then((tex) => {
      // Assume texture is the atlas sheet; compute UV repeat and offset
      if (tex) {
        const img = tex.image;
        const texW = img?.width || region.width;
        const texH = img?.height || region.height;
        const repeat = new Vector2(region.width / texW, region.height / texH);
        const offset = new Vector2(region.x / texW, region.y / texH);
        tex.repeat.set(repeat.x, repeat.y);
        tex.offset.set(offset.x, offset.y);
        tex.needsUpdate = true;
        material.map = tex;
        material.needsUpdate = true;
      }
    });
  }

  // Text content: "Features 3" as headline
  const texts = config.textContent || config.intent?.visualSpec?.textContent || [];
  const headlineItem = texts.find(t => t.role === 'headline') || texts[0];
  if (headlineItem) {
    const textMesh = ctx.fontAtlas.createText(headlineItem.text || 'Features 3', {
      fontSize: 39, // px as spec
      color: config.colors?.paper || '#e8ecf2',
      align: 'center',
      maxWidthPx: 400, // approximate
      letterSpacingPx: 0
    });
    // Position text on the plane surface (z = 0.001 to avoid z-fighting)
    textMesh.position.set(0, 0, 0.001);
    textMesh.scale.set(0.01, 0.01, 0.01); // adjust scale – fontSize 39px is large; scale down for scene units
    group.add(textMesh);
  }

  // No cinematic primitives, no event handlers
  // Cleanup
  const userData = {
    cleanup: () => {
      geometry.dispose();
      material.dispose();
      // Text mesh disposal – fontAtlas may handle internally, but we can remove children
      group.children.forEach(child => {
        if (child.geometry) child.geometry.dispose();
        if (child.material) child.material.dispose();
      });
    }
  };

  group.userData = { ...group.userData, ...userData };

  return group;
}
